export type Model = (GLTF | FBX | OBJ | CustomModel);

export function isGLTFModel(model: Model): model is GLTF {
    const gltf = model as GLTF;
    if (gltf.parser && gltf.parser.json) {
        return true;
    }
    return false;
}

